mapper.select:
select
d.id, d.name, d.address, d.pid, d.level, d.company_id,
c.name as companyName,
concat(ifnull(c.name, ''), case when ifnull(c.name, '') = '' then '' else '-' end, d.name) as label
from department d
left join company c on d.company_id = c.id

     and d.id = #{id}
     and d.name like concat('%', #{name}, '%')
     and d.address like concat('%', #{address}, '%')
     and d.pid = #{pid}
     and d.level = #{level}
     and d.company_id = #{companyId}

order by d.company_id asc, d.id asc
